struct InputBatch {
  uint32_t first_tick{};
  std::array<uint8_t, kMaxBatchInputs> masks{};
  size_t count{};
};

template <typename T>
  bool read_unsigned(T& out) noexcept {
    static_assert(std::is_integral<T>::value && std::is_unsigned<T>::value,
                  "read_unsigned<T> requires an unsigned integral T");
    static_assert(!std::is_same<T, bool>::value,
                  "read_unsigned<bool> is not supported");
    static_assert(sizeof(T) <= sizeof(uint64_t),
                  "read_unsigned<T> supports widths up to 64 bits");

    // Complete-field precheck: consume nothing unless the whole field fits.
    if (!valid_ || remaining() < sizeof(T)) {
      return false;
    }

    // Accumulate into a local candidate so a failure cannot disturb `out`.
    T candidate = 0;
    for (size_t i = 0; i < sizeof(T); ++i) {
      // Widen each byte to T before shifting; the largest shift here is 56.
      const T byte = static_cast<T>(data_[position_ + i]);
      candidate |= static_cast<T>(byte << (i * 8));
    }

    position_ += sizeof(T);
    out = candidate;
    return true;
  }

template <typename T>
  bool write_unsigned(T value) noexcept {
    static_assert(std::is_integral<T>::value && std::is_unsigned<T>::value,
                  "write_unsigned<T> requires an unsigned integral T");
    static_assert(!std::is_same<T, bool>::value,
                  "write_unsigned<bool> is not supported");
    static_assert(sizeof(T) <= sizeof(uint64_t),
                  "write_unsigned<T> supports widths up to 64 bits");

    // Full-field precheck so a partial field is never written.
    if (!valid_ || remaining() < sizeof(T)) {
      return false;
    }

    for (size_t i = 0; i < sizeof(T); ++i) {
      data_[position_ + i] = static_cast<uint8_t>((value >> (i * 8)) & 0xFFu);
    }

    position_ += sizeof(T);
    return true;
  }

inline bool valid_input_batch(const InputBatch& batch) noexcept {
  if (batch.count < 1 || batch.count > kMaxBatchInputs) {
    return false;
  }

  // Verify the tick span fits before adding any ticks, so first_tick + count - 1
  // can never wrap around the uint32 domain.
  if ((std::numeric_limits<uint32_t>::max)() - batch.first_tick <
      static_cast<uint32_t>(batch.count - 1)) {
    return false;
  }

  for (size_t i = 0; i < batch.count; ++i) {
    if (!study_input::valid(batch.masks[i])) {
      return false;
    }
  }
  return true;
}

inline bool encode_input_payload(const InputBatch& batch, Frame& out) noexcept {
  if (!valid_input_batch(batch)) {
    return false;
  }

  // Build into a local candidate so `out` is replaced only on whole-message
  // success. Any field-level write failure leaves `out` untouched.
  Frame candidate{};
  candidate.type = 1;  // diagnostic probe request envelope

  ByteWriter writer(candidate.payload.data(), candidate.payload.size());
  if (!writer.u32(batch.first_tick)) {
    return false;
  }
  if (!writer.u16(static_cast<uint16_t>(batch.count))) {
    return false;
  }
  for (size_t i = 0; i < batch.count; ++i) {
    if (!writer.u8(batch.masks[i])) {
      return false;
    }
  }

  candidate.size = writer.position();
  out = candidate;
  return true;
}

inline bool decode_input_payload(const Frame& frame, InputBatch& out) noexcept {
  // This function never inspects frame.type: routing by type is the caller's
  // responsibility.

  // Reject an impossible declared size before constructing a reader, so the
  // reader can never see more bytes than the payload array actually owns.
  if (frame.size > frame.payload.size()) {
    return false;
  }

  ByteReader reader(frame.payload.data(), frame.size);

  uint32_t first_tick = 0;
  if (!reader.u32(first_tick)) {
    return false;
  }

  uint16_t count16 = 0;
  if (!reader.u16(count16)) {
    return false;
  }

  // Narrowing is not range checking: validate the uint16 explicitly against the
  // batch limit before using it as a count.
  if (count16 < 1 || count16 > kMaxBatchInputs) {
    return false;
  }

  const size_t count = static_cast<size_t>(count16);

  // Exact payload size policy: precisely `count` mask bytes must remain, so
  // both truncated and over-long payloads are rejected.
  if (reader.remaining() != count) {
    return false;
  }

  // Fill a local candidate and validate it before publishing the message.
  // A malformed late mask must not partially update the caller's output.
  InputBatch candidate{};
  candidate.first_tick = first_tick;
  candidate.count = count;
  for (size_t i = 0; i < count; ++i) {
    if (!reader.u8(candidate.masks[i])) {
      return false;
    }
  }

  if (!reader.at_end()) {
    return false;
  }

  if (!valid_input_batch(candidate)) {
    return false;
  }

  out = candidate;
  return true;
}

int exchange(std::uint16_t port) {
    int error=0;
    auto socket=study_net::connect_loopback(port,error);
    if(!socket.valid()) {std::fprintf(stderr,"connect error=%d\n",error);return 1;}
    study_net::InputBatch request{};
    request.first_tick=0x01020304u;request.count=3;
    request.masks[0]=study_input::left;request.masks[1]=0;request.masks[2]=study_input::drop;
    study_net::Frame frame;study_net::EncodedFrame bytes;
    if(!study_net::encode_input_payload(request,frame) || !study_net::encode_frame(frame,bytes)) return fail("encode");
    std::printf("PAYLOAD");
    for(std::size_t i=0;i<frame.size;++i) std::printf(" %02X",unsigned(frame.payload[i]));
    std::puts("");
    std::size_t sent=0;
    while(sent<bytes.size) {
        const auto result=study_net::send_some(socket,bytes.bytes.data()+sent,bytes.size-sent);
        if(result.status!=study_net::StreamStatus::progress) return fail("send");
        sent+=result.count;
    }
    study_net::FrameParser parser;
    bool replied=false;
    for(;;) {
        std::uint8_t scratch[16];
        const auto result=study_net::receive_some(socket,scratch,sizeof(scratch));
        if(result.status==study_net::StreamStatus::error) return fail("receive");
        if(result.status==study_net::StreamStatus::eof) break;
        if(!parser.append(scratch,result.count)) return fail("append");
        for(;;) {
            study_net::Frame reply;
            const auto status=parser.next(reply);
            if(status==study_net::ParseStatus::need_more) break;
            if(status==study_net::ParseStatus::error) return fail("frame");
            if(replied || reply.type!=2) return fail("reply type/count");
            study_net::InputBatch decoded;
            if(!study_net::decode_input_payload(reply,decoded)) return fail("payload grammar");
            if(decoded.first_tick!=request.first_tick || decoded.count!=request.count || decoded.masks!=request.masks) return fail("payload values");
            replied=true;
            // A complete typed response arrived before signalling request EOF.
            if(!study_net::shutdown_send(socket,error)) return fail("shutdown");
        }
    }
    if(!replied || parser.pending_bytes()!=0) return fail("incomplete response");
    std::printf("VERIFIED first_tick=%u count=%zu masks=01,00,10\n",unsigned(request.first_tick),request.count);
    return 0;
}
